"use strict";(globalThis.webpackChunkknowledge_core=globalThis.webpackChunkknowledge_core||[]).push([[7703],{928(e){e.exports=JSON.parse('{"tag":{"label":"Workplace","permalink":"/knowledge-core/es/docs/tags/workplace","description":"Everyday office communication.","allTagsPath":"/knowledge-core/es/docs/tags","count":36,"items":[{"id":"gofluence-handbook/vocabulary/becoming-a-more-empathetic-listener","title":"Becoming a more empathetic listener","description":"Learn twelve key words and phrases (come naturally, undisputed, flawed, biases, common ground, tap into...) and useful phrases for listening with empathy at work.","permalink":"/knowledge-core/es/docs/gofluence-handbook/vocabulary/becoming-a-more-empathetic-listener"},{"id":"gofluence-handbook/grammar/causatives","title":"Causatives","description":"Use have, get, make and let to say that someone or something causes another person or thing to act.","permalink":"/knowledge-core/es/docs/gofluence-handbook/grammar/causatives"},{"id":"gofluence-handbook/vocabulary/computer-and-online-verbs","title":"Computer and online verbs","description":"Learn common verbs for saving data, sharing information, keeping it secure and updating programs, with workplace examples.","permalink":"/knowledge-core/es/docs/gofluence-handbook/vocabulary/computer-and-online-verbs"},{"id":"gofluence-handbook/vocabulary/describing-spaces","title":"Describing spaces","description":"Describe rooms, offices and workstations with this is / these are, there is / there are, prepositions of place and adjectives.","permalink":"/knowledge-core/es/docs/gofluence-handbook/vocabulary/describing-spaces"},{"id":"gofluence-handbook/projects-presentations/discuss-technical-specifications","title":"Discuss technical specifications","description":"Review, adjust and question technical specifications with clear phrases for measurements, materials and feasibility.","permalink":"/knowledge-core/es/docs/gofluence-handbook/projects-presentations/discuss-technical-specifications"},{"id":"gofluence-handbook/projects-presentations/expressing-concerns-and-risks","title":"Expressing concerns and risks","description":"Use clear phrases to introduce a worry, a possible problem or a risk in meetings, projects and discussions about technology.","permalink":"/knowledge-core/es/docs/gofluence-handbook/projects-presentations/expressing-concerns-and-risks"},{"id":"gofluence-handbook/grammar/expressing-possibility","title":"Expressing possibility","description":"Say that something is possible using can, could, may, might and adverbs such as maybe, perhaps and possibly.","permalink":"/knowledge-core/es/docs/gofluence-handbook/grammar/expressing-possibility"},{"id":"gofluence-handbook/grammar/expressing-probability","title":"Expressing probability","description":"Show how sure you are about the past and present with must, may, might, could and can\'t.","permalink":"/knowledge-core/es/docs/gofluence-handbook/grammar/expressing-probability"},{"id":"gofluence-handbook/grammar/first-conditional","title":"First conditional","description":"Talk about possible future actions and their likely results, discuss business options and make suggestions at work.","permalink":"/knowledge-core/es/docs/gofluence-handbook/grammar/first-conditional"},{"id":"gofluence-handbook/tech-products-clients/how-ai-is-shaping-customer-support","title":"How AI is shaping today\'s customer support","description":"Learn key vocabulary to talk about AI in customer support, such as agents, virtual assistants, transforming, personal touch and alongside.","permalink":"/knowledge-core/es/docs/gofluence-handbook/tech-products-clients/how-ai-is-shaping-customer-support"},{"id":"gofluence-handbook/meetings-discussion/agree-and-disagree-in-a-meeting","title":"How to agree and disagree in a meeting","description":"Express full agreement, polite disagreement and partial agreement in meetings with the right phrases and modals.","permalink":"/knowledge-core/es/docs/gofluence-handbook/meetings-discussion/agree-and-disagree-in-a-meeting"},{"id":"gofluence-handbook/tech-products-clients/ask-for-and-provide-technical-assistance","title":"How to ask for and provide technical assistance","description":"Report a technical problem, ask for help, acknowledge an issue, and give clear solutions and instructions.","permalink":"/knowledge-core/es/docs/gofluence-handbook/tech-products-clients/ask-for-and-provide-technical-assistance"},{"id":"gofluence-handbook/meetings-discussion/bring-up-work-issues","title":"How to bring up work issues","description":"Raise problems at work by sharing observations, giving new information and reminders, using the present perfect.","permalink":"/knowledge-core/es/docs/gofluence-handbook/meetings-discussion/bring-up-work-issues"},{"id":"gofluence-handbook/meetings-discussion/communicate-mindfully-at-work","title":"How to communicate mindfully at work","description":"Talk with colleagues in a caring and respectful way by checking in, offering help, sharing opinions and showing appreciation.","permalink":"/knowledge-core/es/docs/gofluence-handbook/meetings-discussion/communicate-mindfully-at-work"},{"id":"gofluence-handbook/meetings-discussion/conduct-a-project-review-meeting","title":"How to conduct a project review meeting","description":"Lead a project review meeting with phrases to set the tone, review the project and outcome, ask for feedback and wrap up.","permalink":"/knowledge-core/es/docs/gofluence-handbook/meetings-discussion/conduct-a-project-review-meeting"},{"id":"gofluence-handbook/meetings-discussion/debate-ideas","title":"How to debate ideas III","description":"State opinions assertively, make arguments and politely raise objections in a work debate.","permalink":"/knowledge-core/es/docs/gofluence-handbook/meetings-discussion/debate-ideas"},{"id":"gofluence-handbook/tech-products-clients/describe-a-product","title":"How to describe a product","description":"Describe what a product has and does using feature phrases, made of vs made from, causative verbs and compound adjectives.","permalink":"/knowledge-core/es/docs/gofluence-handbook/tech-products-clients/describe-a-product"},{"id":"gofluence-handbook/tech-products-clients/discuss-using-ai-tools-at-work","title":"How to discuss using AI tools at work","description":"Ask colleagues about the AI tools they use, ask follow-up questions, and describe what AI tools do with simple structures.","permalink":"/knowledge-core/es/docs/gofluence-handbook/tech-products-clients/discuss-using-ai-tools-at-work"},{"id":"gofluence-handbook/meetings-discussion/give-and-ask-for-feedback","title":"How to give and ask for feedback","description":"Ask for and give feedback politely at work with verbs for opinions and modals like would and could.","permalink":"/knowledge-core/es/docs/gofluence-handbook/meetings-discussion/give-and-ask-for-feedback"},{"id":"gofluence-handbook/tech-products-clients/respond-to-feedback-from-clients","title":"How to respond to feedback from clients","description":"Respond to negative client feedback with apologies, empathy, clear solutions, alternatives and a friendly follow-up.","permalink":"/knowledge-core/es/docs/gofluence-handbook/tech-products-clients/respond-to-feedback-from-clients"},{"id":"gofluence-handbook/meetings-discussion/share-thoughts-in-a-meeting","title":"How to share thoughts in a meeting","description":"Ask for and give opinions in meetings using useful verbs and nouns such as think, feel, opinion and views.","permalink":"/knowledge-core/es/docs/gofluence-handbook/meetings-discussion/share-thoughts-in-a-meeting"},{"id":"gofluence-handbook/tech-products-clients/talk-about-apps","title":"How to talk about apps","description":"Describe app functions, discuss pros and cons, and talk about plans and pricing for desktop, mobile and web apps.","permalink":"/knowledge-core/es/docs/gofluence-handbook/tech-products-clients/talk-about-apps"},{"id":"gofluence-handbook/grammar/making-comparisons","title":"Making comparisons","description":"Compare people, tools, options and results at work with comparative adjectives and as ... as.","permalink":"/knowledge-core/es/docs/gofluence-handbook/grammar/making-comparisons"},{"id":"gofluence-handbook/grammar/making-deductions","title":"Making deductions","description":"Use clues to work out what is probably true or what the problem is, with must, might, could and can\'t.","permalink":"/knowledge-core/es/docs/gofluence-handbook/grammar/making-deductions"},{"id":"gofluence-handbook/grammar/making-predictions","title":"Making predictions","description":"Say what you think will happen at work, with the right level of certainty, using will, may, might and could.","permalink":"/knowledge-core/es/docs/gofluence-handbook/grammar/making-predictions"},{"id":"gofluence-handbook/meetings-discussion/making-suggestions","title":"Making suggestions","description":"Make suggestions with modals and question words, and discuss business options with conditionals and phrases like what if and an alternative.","permalink":"/knowledge-core/es/docs/gofluence-handbook/meetings-discussion/making-suggestions"},{"id":"gofluence-handbook/projects-presentations/manage-scope-creep","title":"Manage scope creep","description":"Use infinitives of purpose (to, so as to, in order to, not to) to set goals and communicate limits and avoid scope creep.","permalink":"/knowledge-core/es/docs/gofluence-handbook/projects-presentations/manage-scope-creep"},{"id":"gofluence-handbook/vocabulary/most-common-prefixes","title":"Most commonly used prefixes","description":"Learn ten common English prefixes (anti-, pro-, pre-, post-, ex-, in-, im-, non-, un-, re-) and use them to build and understand new words at work.","permalink":"/knowledge-core/es/docs/gofluence-handbook/vocabulary/most-common-prefixes"},{"id":"gofluence-handbook/grammar/must","title":"Must","description":"Use must to express obligation and to make confident guesses about people and situations at work.","permalink":"/knowledge-core/es/docs/gofluence-handbook/grammar/must"},{"id":"gofluence-handbook/grammar/object-and-subject-pronouns","title":"Object and subject pronouns","description":"Choose the right subject, object and possessive pronouns to avoid repeating names in emails, meetings and messages.","permalink":"/knowledge-core/es/docs/gofluence-handbook/grammar/object-and-subject-pronouns"},{"id":"gofluence-handbook/vocabulary/office-rooms-furniture-and-appliances","title":"Office rooms, furniture and appliances","description":"Learn the words for the rooms, furniture and equipment in an office and use them to describe your workplace and give directions.","permalink":"/knowledge-core/es/docs/gofluence-handbook/vocabulary/office-rooms-furniture-and-appliances"},{"id":"gofluence-handbook/grammar/prepositions-of-position","title":"Prepositions of position","description":"Describe where people, things and files are, using inside, outside, above, below, next to, between and more.","permalink":"/knowledge-core/es/docs/gofluence-handbook/grammar/prepositions-of-position"},{"id":"gofluence-handbook/projects-presentations/present-a-project-proposal","title":"Present a project proposal","description":"Follow a clear structure to present a project proposal with an outline, goals, phases, costs and a strong conclusion.","permalink":"/knowledge-core/es/docs/gofluence-handbook/projects-presentations/present-a-project-proposal"},{"id":"gofluence-handbook/projects-presentations/present-a-project-status-report","title":"Present a project status report","description":"Talk about progress, important events and the timeline of a project using the right verb tenses and phrases.","permalink":"/knowledge-core/es/docs/gofluence-handbook/projects-presentations/present-a-project-status-report"},{"id":"gofluence-handbook/grammar/present-perfect-vs-simple-past","title":"Present perfect vs. simple past","description":"Choose between the present perfect and the simple past to talk about experience, finished actions and results that matter now.","permalink":"/knowledge-core/es/docs/gofluence-handbook/grammar/present-perfect-vs-simple-past"},{"id":"gofluence-handbook/grammar/zero-conditional","title":"Zero conditional","description":"Use the zero conditional to describe routines, rules and things that always happen at work.","permalink":"/knowledge-core/es/docs/gofluence-handbook/grammar/zero-conditional"}],"unlisted":false}}')}}]);